/* ==========================================
   COMPONENT: QuickScratchpad
   Notes/scratchpad with multi-tab editing
   ========================================== */

.scratchpad {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  position: relative;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: none;
  transition: background-color 0.3s, color 0.3s;
}

@media (min-width: 640px) {
  .scratchpad { padding: 1.5rem; }
}

.scratchpad::-webkit-scrollbar { display: none; }

.scratchpad.theme-light { background-color: #FFFFFF; color: #171717; }
.scratchpad.theme-dark { background-color: #18181B; color: white; }

/* Header */
.scratchpad-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  border-bottom: 2px solid;
  padding-bottom: 0.75rem;
  margin-bottom: 0.75rem;
}

.scratchpad-header.theme-light { border-color: #171717; }
.scratchpad-header.theme-dark { border-color: #3F3F46; }

.scratchpad-title-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.scratchpad-icon-wrap {
  background-color: #171717;
  color: #F25C23;
  padding: 0.375rem;
  border-radius: 0.375rem;
  border: 1px solid #3F3F46;
}

.scratchpad-icon {
  width: 1.25rem;
  height: 1.25rem;
  color: #F25C23;
}

.scratchpad-title {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

@media (min-width: 640px) {
  .scratchpad-title { font-size: 1.875rem; }
}

.scratchpad-title.theme-light { color: #171717; }
.scratchpad-title.theme-dark { color: white; }

/* Toolbar */
.scratchpad-toolbar {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  flex-wrap: wrap;
}

/* Toolbar buttons – base */
.scratchpad-btn {
  padding: 0.375rem 0.625rem;
  border-radius: 0.375rem;
  border: 2px solid;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 700;
  transition: all 0.2s;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.375rem;
  box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.scratchpad-btn:active { transform: translateY(2px); }

.scratchpad-btn.theme-light {
  background-color: #F5F5F3;
  border-color: #171717;
  color: #171717;
}

.scratchpad-btn.theme-light:hover {
  background-color: #F25C23;
  color: white;
}

.scratchpad-btn.theme-dark {
  background-color: #27272A;
  border-color: #3F3F46;
  color: #d6d3d1;
}

.scratchpad-btn.theme-dark:hover {
  background-color: #F25C23;
  color: white;
}

.scratchpad-btn.saving,
.scratchpad-btn.unsaved {
  background-color: #F25C23;
  color: white;
  border-color: #171717;
}

.scratchpad-btn.unsaved {
  animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

.scratchpad-btn.locked-active {
  background-color: #f59e0b;
  color: #171717;
  border-color: #f59e0b;
}

.scratchpad-btn.copied-active {
  background-color: #F25C23;
  color: white;
  border-color: #171717;
}

/* Icon-only small button variant */
.scratchpad-icon-btn {
  padding: 0.375rem;
  border-radius: 0.375rem;
  border: 2px solid;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  font-weight: 700;
  transition: all 0.2s;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.scratchpad-icon-btn.theme-light {
  background-color: #F5F5F3;
  border-color: #171717;
  color: #171717;
}

.scratchpad-icon-btn.theme-light:hover {
  background-color: #F25C23;
  color: white;
}

.scratchpad-icon-btn.theme-dark {
  background-color: #27272A;
  border-color: #3F3F46;
  color: #d6d3d1;
}

.scratchpad-icon-btn.theme-dark:hover {
  background-color: #F25C23;
  color: white;
}

.scratchpad-icon-btn.locked-active {
  background-color: #f59e0b;
  color: #171717;
  border-color: #f59e0b;
}

.scratchpad-icon-btn.copied-active {
  background-color: #F25C23;
  color: white;
  border-color: #171717;
}

.scratchpad-btn-icon {
  width: 0.875rem;
  height: 0.875rem;
  stroke-width: 2.5;
}

.scratchpad-btn-text-sm {
  display: none;
}

@media (min-width: 640px) {
  .scratchpad-btn-text-sm { display: inline; }
}

/* Note tabs */
.scratchpad-tabs {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  margin-bottom: 0.75rem;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.scratchpad-tabs::-webkit-scrollbar { display: none; }

.scratchpad-tab {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border-radius: 0.375rem;
  border: 1px solid;
  font-size: 0.75rem;
  font-weight: 700;
  transition: all 0.2s;
  cursor: pointer;
  white-space: nowrap;
}

.scratchpad-tab.active {
  background-color: #F25C23;
  color: white;
  border-color: #F25C23;
}

.scratchpad-tab.inactive.theme-light {
  background-color: #F5F5F3;
  color: #171717;
  border-color: rgba(23, 23, 23, 0.3);
}

.scratchpad-tab.inactive.theme-light:hover {
  border-color: #171717;
}

.scratchpad-tab.inactive.theme-dark {
  background-color: #27272A;
  color: #d6d3d1;
  border-color: #3F3F46;
}

.scratchpad-tab.inactive.theme-dark:hover {
  border-color: #F25C23;
}

.scratchpad-tab-icon {
  width: 0.75rem;
  height: 0.75rem;
  flex-shrink: 0;
}

.scratchpad-tab-icon.locked { color: #f59e0b; }
.scratchpad-tab.active .scratchpad-tab-icon { color: white; }

.scratchpad-tab-name {
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 90px;
}

.scratchpad-tab-delete {
  margin-left: 0.25rem;
  cursor: pointer;
  background: transparent;
  border: none;
  padding: 0;
  line-height: 0;
}

.scratchpad-tab-delete:hover { color: #171717; }

.scratchpad-tab-delete-icon {
  width: 0.75rem;
  height: 0.75rem;
}

/* Title input row */
.scratchpad-title-input-row {
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.scratchpad-title-input {
  width: 100%;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  background: transparent;
  border-bottom: 1px solid;
  padding-bottom: 0.25rem;
  transition: border-color 0.2s;
}

.scratchpad-title-input:focus { outline: none; border-color: #F25C23; }

.scratchpad-title-input.theme-light {
  color: #171717;
  border-color: rgba(23, 23, 23, 0.2);
}

.scratchpad-title-input.theme-dark {
  color: white;
  border-color: #3F3F46;
}

.scratchpad-title-input.locked {
  cursor: not-allowed;
  opacity: 0.8;
  border-color: rgba(245, 158, 11, 0.5);
}

.scratchpad-locked-badge {
  font-size: 10px;
  font-family: var(--font-mono);
  font-weight: 700;
  color: #f59e0b;
  background-color: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.3);
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
  white-space: nowrap;
}

.scratchpad-locked-badge-icon {
  width: 0.75rem;
  height: 0.75rem;
}

/* Textarea editor */
.scratchpad-editor-wrap {
  flex: 1;
  margin: 0.5rem 0;
  display: flex;
  flex-direction: column;
}

.scratchpad-editor {
  width: 100%;
  min-height: 150px;
  padding: 0.75rem;
  border-radius: 0.5rem;
  border: 2px solid;
  font-family: var(--font-mono);
  font-size: 0.75rem;
  line-height: 1.625;
  resize: none;
  transition: border-color 0.2s;
  overflow: hidden;
}

.scratchpad-editor:focus { outline: none; border-color: #F25C23; }

.scratchpad-editor.theme-light {
  background-color: #F5F5F3;
  border-color: #171717;
  color: #171717;
}

.scratchpad-editor.theme-light::placeholder { color: rgba(23,23,23,0.5); }

.scratchpad-editor.theme-dark {
  background-color: #27272A;
  border-color: #3F3F46;
  color: #e5e5e4;
}

.scratchpad-editor.theme-dark::placeholder { color: #57534e; }

.scratchpad-editor.locked.theme-light {
  background-color: #F0EFF0;
  border-color: rgba(245, 158, 11, 0.4);
  cursor: not-allowed;
}

.scratchpad-editor.locked.theme-dark {
  background-color: #202023;
  border-color: rgba(245, 158, 11, 0.4);
  cursor: not-allowed;
}

/* Footer */
.scratchpad-footer {
  padding-top: 0.75rem;
  border-top: 2px solid;
  margin-top: 0.5rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 11px;
  font-family: var(--font-mono);
}

.scratchpad-footer.theme-light { border-color: #171717; color: rgba(23,23,23,0.7); }
.scratchpad-footer.theme-dark { border-color: #3F3F46; color: #78716c; }

.scratchpad-footer-left {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.scratchpad-autosave-label {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  cursor: pointer;
  opacity: 0.7;
  transition: opacity 0.2s;
  user-select: none;
  font-size: 10px;
}

.scratchpad-autosave-label:hover { opacity: 1; }

.scratchpad-autosave-checkbox {
  width: 0.75rem;
  height: 0.75rem;
  accent-color: #F25C23;
  cursor: pointer;
  border-radius: 0.125rem;
}

.scratchpad-autosave-on { color: #F25C23; font-weight: 600; }
.scratchpad-autosave-off { color: #78716c; }

.scratchpad-status {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  font-weight: 700;
}

.scratchpad-status-icon {
  width: 0.75rem;
  height: 0.75rem;
}

.scratchpad-status.saved { color: #F25C23; }
.scratchpad-status.saving { color: #f59e0b; }
.scratchpad-status.unsaved { color: #F25C23; }
.scratchpad-status.locked-status { color: #f59e0b; }
.scratchpad-status.error { color: #f43f5e; }
